/**
 * Type declaration for apiClient.js when imported as text via wrangler rules
 *
 * Wrangler is configured to import this file as raw text (type = "Text"),
 * so it's exposed as a string containing the JavaScript source code.
 *
 * @see wrangler.toml rules configuration
 * @see Story 4.2 - Shared API Client Module
 */
declare const apiClientModule: string;
export default apiClientModule;
